import React, { useEffect, useState } from "react";
import { GraduationCap, Award, BookOpen, Star, Users } from "lucide-react";
import api from "../api/axios";
import Loading from "../Components/Loading";

const Teachers = () => {
  const [teachers, setTeachers] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchTeachers = async () => {
      setLoading(true);
      try {
        const res = await api.get("/public/teachers");
        if (res.data.success) {
          setTeachers(res.data.data);
        }
      } catch (err) {
        console.error("Failed to fetch teachers:", err);
      } finally {
        setLoading(false);
      }
    };

    fetchTeachers();
  }, []);

  if (loading) return <Loading />;

  return (
    <div className="min-h-screen bg-slate-50 py-12 px-4 md:px-8 lg:px-12">
      <div className="max-w-7xl mx-auto space-y-12">
        {/* Header */}
        <div className="text-center space-y-3 max-w-3xl mx-auto">
          <div className="inline-flex items-center gap-2 bg-[#d49539]/15 text-[#304b62] px-4 py-1.5 rounded-full text-xs md:text-sm font-bold tracking-wide">
            <GraduationCap size={16} className="text-[#d49539]" /> Verified Faculty & Mentors
          </div>
          <h1 className="text-3xl md:text-5xl font-black text-[#304b62] tracking-tight">
            Meet Our Expert Educators
          </h1>
          <p className="text-slate-600 text-base md:text-lg">
            Dedicated subject specialists committed to conceptual clarity, personalized student mentoring, and consistent academic excellence.
          </p>
        </div>

        {/* Teachers Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {teachers.map((teacher) => (
            <div
              key={teacher._id}
              className="bg-white rounded-2xl shadow-md hover:shadow-xl transition-all duration-300 border border-slate-200 overflow-hidden flex flex-col justify-between group"
            >
              {/* Card Top */}
              <div>
                {/* Photo & Header */}
                <div className="relative h-60 overflow-hidden bg-[#304b62]">
                  <img
                    src={teacher.photo_url || "https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=400&q=80"}
                    alt={teacher.name}
                    className="w-full h-full object-cover object-top group-hover:scale-105 transition-transform duration-500"
                  />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-transparent to-transparent" />
                  <div className="absolute bottom-4 left-4 right-4 text-white">
                    <h3 className="text-xl font-extrabold">{teacher.name}</h3>
                    <div className="flex items-center gap-2 text-xs text-[#d49539] font-semibold mt-0.5">
                      <Star size={14} className="fill-[#d49539]" /> {teacher.rating || 4.8} / 5.0 Rating • {teacher.experience_years}+ Years Exp
                    </div>
                  </div>
                </div>

                {/* Body */}
                <div className="p-6 space-y-4">
                  {/* Qualifications */}
                  <div className="space-y-1">
                    <div className="text-xs font-bold text-slate-400 uppercase tracking-wider flex items-center gap-1.5">
                      <Award size={13} className="text-[#d49539]" /> Qualifications:
                    </div>
                    <div className="flex flex-wrap gap-1.5">
                      {teacher.qualifications?.map((q, idx) => (
                        <span key={idx} className="bg-slate-100 text-[#304b62] text-xs font-semibold px-2 py-0.5 rounded">
                          {q}
                        </span>
                      ))}
                    </div>
                  </div>

                  {/* Specializations */}
                  <div className="space-y-1">
                    <div className="text-xs font-bold text-slate-400 uppercase tracking-wider flex items-center gap-1.5">
                      <BookOpen size={13} className="text-[#d49539]" /> Teaches:
                    </div>
                    <div className="flex flex-wrap gap-1.5">
                      {teacher.specializations?.map((s, idx) => (
                        <span key={idx} className="bg-[#f6d6a0]/40 text-[#304b62] text-xs font-semibold px-2.5 py-0.5 rounded-full border border-[#d49539]/30">
                          {s}
                        </span>
                      ))}
                    </div>
                  </div>

                  {/* Bio */}
                  <p className="text-xs md:text-sm text-slate-600 line-clamp-3 leading-relaxed">
                    {teacher.bio || "Experienced educator dedicated to student success and active concept building."}
                  </p>
                </div>
              </div>

              {/* Card Footer */}
              <div className="p-6 pt-0 border-t border-slate-100 mt-2 bg-slate-50/50">
                <div className="pt-3 flex items-center justify-between text-xs text-slate-500 font-medium">
                  <span className="flex items-center gap-1">
                    <Users size={14} className="text-[#304b62]" /> Active Mentor
                  </span>
                  <span className="text-[#304b62] font-bold">Apex Academy</span>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Teachers;
